    "subtitle": "Hanboro FaceShift Series – FaceShift Automatic“Six faces. One bold identity.”A mechanical tribute to transformation and legacy, this timepiece features six rotating face masks, each appearing every four hours. Every face tells a story—power, wisdom, rebellion, honor, fearlessness, and clarity—capturing the many dimensions of identity.The fan-shaped crystal bezel draws from traditional art forms, and in every box, you’ll find a handcrafted ceremonial fan, symbolizing elegance and heritage. Paired with luminous accents, exposed mechanics, and a bold silhouette, this watch is designed for those who wear their story with pride. Specifications Movement: Japanese CITIZEN 8215 mechanical movement \"Thickness: 5.67mm, 21 gems, Frequency 21600 times/hour, Stop second function, Automatic/manual loading Power Reserve: Approx. 42 Hours Jewels: 21+ Jewels Frequency: 21,600 VPH Case Material: 316L Stainless Steel Glass: Synthetic Sapphire Crystal Case Diameter: 43mm Water Resistance: 50M (5 ATM) Strap: Fluororubber / Stainless Steel Clasp: Butterfly Clasp / Tang Buckle Warranty: 24 Months Official Manufacturer Warranty Compliance & Care Country of Origin: People’s Republic of China Manufacturer: Guangzhou Hengbaoluo Technology Co., Ltd. Importer / Packer: Rise N Be Original Lifestyle Pvt Ltd, Building No. 3, 4th Floor, Block M, DLF City Phase II, Road Number 5, Sector 25, Gurugram, Haryana 122008, India",
