    "title": "Hanboro Transparence Excellence Automatic Skeleton Watch (Rose Gold & Silver)",
    "subtitle": "Experience timeless craftsmanship with the Hanboro Transparence Excellence Automatic Watch – a luxury men’s timepiece designed for those who value precision and style. Crafted with a diamond-cut stainless steel case and a scratch-resistant sapphire crystal, this watch showcases durability with a premium finish.The double-sided skeleton flywheel dial reveals the beauty of the mechanical movement, while luminous markers ensure perfect readability day or night. Powered by an automatic movement with a 40-hour power reserve, it blends performance with sophistication.Choose between a stainless steel bracelet or genuine leather strap, secured with a double-press butterfly clasp for all-day comfort. With 50M water resistance, the Transparence Excellence is built for both everyday wear and refined occasions.Whether you’re building your collection or searching for a statement accessory, this automatic skeleton watch is designed to turn heads and elevate your style. Specifications Movement: Japan CITIZEN 9015 mechanical movement:, Thickness: 3.9mm, Diamond count; 24 pieces, Frequency 28800 times/hour, Automatic/manual winding Power Reserve: 45 Hours Jewels: 24 Synthetic Rubies & Heat-Blued Screws Frequency: 28,800 VPH (4.0 Hz) Case Material: STAINLESS STEEL Glass: SAPPHIRE CRYSTAL Case Diameter: 41mm Water Resistance: 50M (5 ATM) Strap: STAINLESS STELL Clasp: Butterfly Clasp Warranty: 24.0 Months Official Manufacturer Warranty Compliance & Care Country of Origin: People’s Republic of China Manufacturer: Guangzhou Hengbaoluo Technology Co., Ltd. Importer / Packer: Rise N Be Original Lifestyle Pvt Ltd, Building No. 3, 4th Floor, Block M, DLF City Phase II, Road Number 5, Sector 25, Gurugram, Haryana 122008, India",
