    "id": "hbr-9038-auto-black",
    "sku": "HBR-9038-AUTO-BLACK",
    "modelNumber": "9038",
    "name": "Hanboro Nautilus Spirit – Great Wave Edition (Midnight Wave)",
    "title": "Hanboro Nautilus Spirit – Great Wave Edition (Midnight Wave)",
    "subtitle": "Hanboro Nautilus Spirit – Ocean Wave EditionA fusion of transparency, mechanics, and artistry.The Hanboro Nautilus Spirit is designed for those who appreciate both innovation and style. Featuring a square transparent case with crystal glass bezel, it offers a bold and futuristic presence on the wrist. The hollow wave-pattern dial, enhanced with luminous detailing, creates a striking visual inspired by the power of the ocean.At its heart, the original Hangzhou 7500 hollow mechanical movement beats with precision – delivering a swing frequency of 28,800 vibrations/hour, a 40-hour power reserve, and accuracy within ±3 seconds/day. The exhibition back reveals the intricate mechanics in motion, thanks to a diamond-knife crafted crystal mirror for ultimate clarity.Finished with a soft silicone strap for comfort and durability, and equipped with a secure butterfly spring clasp, this timepiece is made for daily wear. With deep waterproofing, it stands resilient through handwashing, rain, and swimming – without compromising its elegance. Specifications Movement: Japan CITIZEN 9015 mechanical movement:, Thickness: 3.9mm, Diamond count; 24 pieces, Frequency 28800 times/hour, Automatic/manual winding Power Reserve: ~42 Hours Jewels: 24 Synthetic Rubies Frequency: 28,800 BPH (4 Hz) Case Material: ACRYLIC Glass: GLASS Case Diameter: 52mm Water Resistance: 100M Strap: SILICONE () Clasp: Butterfly Clasp Warranty: 24.0 Months Official Manufacturer Warranty Compliance & Care Country of Origin: People’s Republic of China Manufacturer: Guangzhou Hengbaoluo Technology Co., Ltd. Importer / Packer: Rise N Be Original Lifestyle Pvt Ltd, Building No. 3, 4th Floor, Block M, DLF City Phase II, Road Number 5, Sector 25, Gurugram, Haryana 122008, India",
