    "title": "Hanboro A200 Reserve – Automatic Power Reserve Stainless Steel Watch (Black & Silver)",
    "subtitle": "The Hanboro A200 Reserve is a study in restrained power and modern mechanical precision. Designed for those who understand true horology, its deep black sunray dial creates a dramatic contrast against the polished stainless steel case and bracelet.Powered by the original Hangzhou A200 automatic movement, it delivers reliable performance with a refined energy reserve display and small seconds complication — a quiet nod to traditional watchmaking mastery.The sapphire crystal enhances clarity while protecting the minimalist dial architecture. With its balanced proportions and clean aesthetic, the A200 Reserve is a statement of sophistication — engineered for collectors who value precision, purity, and presence. Specifications Movement: Hangzhou A200 automatic mechanical movement, Thickness: approx 5mm, Power Reserve: ~40 hours, Frequency 21600 times/hour, Stop second function, Automatic/manual winding Power Reserve: 35 Hours (Top-Mounted Gauge) Jewels: 22 Synthetic Rubies Frequency: 21,600 VPH (3.0 Hz) Case Material: STAINLESS STEEL Glass: SAPPHIRE CRYSTAL Case Diameter: 42mm Water Resistance: 50M (5 ATM) Strap: STAINLESS STEEL Clasp: double-pressed butterfly clasp, Warranty: 24.0 Months Official Manufacturer Warranty Compliance & Care Country of Origin: People’s Republic of China Manufacturer: Guangzhou Hengbaoluo Technology Co., Ltd. Importer / Packer: Rise N Be Original Lifestyle Pvt Ltd, Building No. 3, 4th Floor, Block M, DLF City Phase II, Road Number 5, Sector 25, Gurugram, Haryana 122008, India",
