    "subtitle": "The Hanboro Meridian is a bold expression of architectural luxury and mechanical mastery. Crafted from 304 fine steel using precision diamond-knife angle finishing, the octagonal case is elevated with 56 square-cut crystals — delivering brilliance without compromising strength.At its heart beats the original Shanghai JHS17 multifunction automatic movement, offering 40 hours of power reserve and refined timekeeping precision. The dial showcases a complete complication layout — date, day, small seconds, and celestial sun-moon display — all enhanced with luminous markers for powerful night visibility.Protected by sapphire crystal and water resistant up to 100 meters, the Meridian is built for those who demand elegance with endurance.A timepiece of structure. Brilliance. Authority. Specifications Movement: Shanghai JHS17 multifunction automatic movement, Power Reserve: 40 hours, Frequency 21600 times/hour, Stop second function, Automatic/manual winding Power Reserve: 44 Hours Jewels: 24 Jewels Frequency: 28,800 VPH (4.0 Hz) Case Material: STAINLESS STEEL Glass: SAPPHIRE CRYSTAL Case Diameter: 38mm Water Resistance: 50M (5 ATM) Strap: STAINLESS STEEL Clasp: double-pressed butterfly clasp, Warranty: 24.0 Months Official Manufacturer Warranty Compliance & Care Country of Origin: People’s Republic of China Manufacturer: Guangzhou Hengbaoluo Technology Co., Ltd. Importer / Packer: Rise N Be Original Lifestyle Pvt Ltd, Building No. 3, 4th Floor, Block M, DLF City Phase II, Road Number 5, Sector 25, Gurugram, Haryana 122008, India",
