    "subtitle": "The OceanStrike “Purple Abyss” is designed for those who move differently. Its deep violet gradient dial shifts from shadow to brilliance under light, creating a rare and commanding presence.Inside, the Shanghai JHS08 automatic movement delivers precision with a 40-hour reserve and full calendar functionality. The skeletonized tourbillon window exposes the mechanical core, enhanced by luminous markers for bold night visibility.With 100M water resistance and a ceramic rotating bezel, Purple Abyss merges technical diving capability with avant-garde luxury. Specifications Movement: Quartz multifunction chronograph movement, 100M water resistance, Stainless steel case Power Reserve: Long-life Energy Cell (3-Year Continuous Sweep) Jewels: Multi-Jeweled Precision Chrono Module Frequency: High-Beat Smooth Sweep (32,768 Hz / Precision Column-Wheel Action) Case Material: STAINLESS STEEL Glass: SAPPHIRE CRYSTAL Case Diameter: 42mm Water Resistance: 100M (10 ATM) Strap: STAINLESS STEEL Clasp: double-pressed butterfly clasp, Warranty: 24.0 Months Official Manufacturer Warranty Compliance & Care Country of Origin: People’s Republic of China Manufacturer: Guangzhou Hengbaoluo Technology Co., Ltd. Importer / Packer: Rise N Be Original Lifestyle Pvt Ltd, Building No. 3, 4th Floor, Block M, DLF City Phase II, Road Number 5, Sector 25, Gurugram, Haryana 122008, India",
