    "subtitle": "The OceanStrike “Lagoon Surge” channels coastal sophistication with its cool teal gradient dial. Elegant yet powerful, the dial houses a complete multifunction complication layout with luminous clarity for day or night readability.Driven by the Shanghai JHS08 automatic movement, it offers a 40-hour power reserve and visible tourbillon architecture beneath sapphire crystal. The unidirectional ceramic bezel reinforces its diver heritage.Balanced, refined, and engineered for performance, Lagoon Surge is luxury engineered for motion. Specifications Movement: Quartz multifunction chronograph movement, 100M water resistance, Stainless steel case Power Reserve: 45 Hours Jewels: 27 Synthetic Rubies Frequency: 28,800 VPH (4.0 Hz) Case Material: STAINLESS STEEL Glass: SAPPHIRE CRYSTAL Case Diameter: 42mm Water Resistance: 100M (10 ATM) Strap: STAINLESS STEEL Clasp: double-pressed butterfly clasp, Warranty: 24.0 Months Official Manufacturer Warranty Compliance & Care Country of Origin: People’s Republic of China Manufacturer: Guangzhou Hengbaoluo Technology Co., Ltd. Importer / Packer: Rise N Be Original Lifestyle Pvt Ltd, Building No. 3, 4th Floor, Block M, DLF City Phase II, Road Number 5, Sector 25, Gurugram, Haryana 122008, India",
