    "subtitle": "The OceanStrike “Volcanic Reef” is raw energy contained in steel. Its fiery sunburst orange dial radiates intensity, contrasted by a precision ceramic bezel and polished 304 steel case.Equipped with a six-hand multifunction layout, including 24-hour, day, month, and calendar displays, it is powered by the robust Shanghai JHS08 mechanical movement. The visible Geneva-pattern tourbillon mechanism delivers horological theatre at every glance.Water-resistant to 100 meters and secured with a solid steel bracelet, Volcanic Reef is built for those who prefer bold dominance over subtlety. Specifications Movement: Quartz multifunction chronograph movement, 100M water resistance, Stainless steel case Power Reserve: 45 Hours Jewels: 27 Synthetic Rubies Frequency: 28,800 VPH (4.0 Hz) Case Material: STAINLESS STEEL Glass: SAPPHIRE CRYSTAL Case Diameter: 42mm Water Resistance: 100M (10 ATM) Strap: STAINLESS STEEL Clasp: double-pressed butterfly clasp, Warranty: 24.0 Months Official Manufacturer Warranty Compliance & Care Country of Origin: People’s Republic of China Manufacturer: Guangzhou Hengbaoluo Technology Co., Ltd. Importer / Packer: Rise N Be Original Lifestyle Pvt Ltd, Building No. 3, 4th Floor, Block M, DLF City Phase II, Road Number 5, Sector 25, Gurugram, Haryana 122008, India",
