    "name": "Casino Series: Roulette Royale Automatic Watch (Rose Gold & Monte Carlo Red)",
    "title": "Casino Series: Roulette Royale Automatic Watch (Rose Gold & Monte Carlo Red)",
    "subtitle": "The Hanboro Roulette Royale – Red Gem Edition is a statement in mechanical theatre. Inspired by the geometry and rhythm of a classic roulette wheel, its dial is meticulously structured with concentric detailing and deep red crystal accents that create remarkable depth and symmetry.Encased in rose gold-toned steel, the watch carries a commanding presence while maintaining refined elegance. The automatic movement beats beneath the surface, visible through its open architecture — a reminder that true luxury lies in mechanical precision, not decoration.Balanced by a supple leather strap and timeless proportions, this timepiece is crafted for collectors who appreciate design with intent.Not made for everyone.Made for those who understand presence. Specifications Movement: Automatic mechanical movement, Power Reserve: ~40 hours, Frequency 21600 times/hour, Stop second function, Automatic/manual winding Power Reserve: 50 Hours Jewels: 31 Synthetic Rubies & Micro Ceramic Ball Bearings Frequency: 28,800 VPH (4.0 Hz) Case Material: STAINLESS STEEL Glass: SAPPHIRE CRYSTAL Case Diameter: 45.5mm Water Resistance: 50M (5 ATM) Strap: LEATHER Clasp: Push Button Hidden Clasp Warranty: 24.0 Months Official Manufacturer Warranty Compliance & Care Country of Origin: People’s Republic of China Manufacturer: Guangzhou Hengbaoluo Technology Co., Ltd. Importer / Packer: Rise N Be Original Lifestyle Pvt Ltd, Building No. 3, 4th Floor, Block M, DLF City Phase II, Road Number 5, Sector 25, Gurugram, Haryana 122008, India",
