    "name": "Hanboro Hemisphera – Dual Hemisphere Automatic Moonphase Watch (Deep Sky Blue)",
    "title": "Hanboro Hemisphera – Dual Hemisphere Automatic Moonphase Watch (Deep Sky Blue)",
    "subtitle": "The Hanboro Hemisphera is a mechanical tribute to the world above us. Designed around a rare dual-hemisphere complication, it simultaneously tracks 24-hour sun and moon cycles for both the Northern and Southern hemispheres — a feature inspired by global navigation and celestial mechanics.Encased in precision-crafted 316L stainless steel with diamond-knife finishing, the 44mm architecture delivers strength with refined detailing. At 12 o’clock, the open flywheel reveals the beating heart of the automatic movement, oscillating at 21,600 vibrations per hour and offering a 40-hour power reserve.The 3D multi-functional dial integrates:Northern Hemisphere 24-hour sun & moon displaySouthern Hemisphere 24-hour sun & moon displayOpen mechanical flywheelLuminous hour markersProtected by a sapphire crystal and water-resistant up to 100 meters, the Hemisphera blends global sophistication with mechanical depth.Built for collectors who think beyond borders. Specifications Movement: Automatic mechanical movement, Power Reserve: ~40 hours, Frequency 21600 times/hour, Stop second function, Automatic/manual winding Power Reserve: 48 Hours Jewels: 26 Synthetic Rubies Frequency: 28,800 VPH (4.0 Hz) Case Material: STAINLESS STEEL Glass: SAPPHIRE CRYSTAL Case Diameter: 44mm Water Resistance: 100M (10 ATM) Strap: STAINLESS STEEL Clasp: double-press butterfly clasp Warranty: 24.0 Months Official Manufacturer Warranty Compliance & Care Country of Origin: People’s Republic of China Manufacturer: Guangzhou Hengbaoluo Technology Co., Ltd. Importer / Packer: Rise N Be Original Lifestyle Pvt Ltd, Building No. 3, 4th Floor, Block M, DLF City Phase II, Road Number 5, Sector 25, Gurugram, Haryana 122008, India",
