    "sku": "HBR-2712-AUTO-RG-TIRANGA",
    "modelNumber": "2712",
    "name": "Hanboro WorldMaster Tricolour – 3D Globe Open-Heart Automatic Watch (Rose Gold)",
    "title": "Hanboro WorldMaster Tricolour – 3D Globe Open-Heart Automatic Watch (Rose Gold)",
    "subtitle": "The Hanboro WorldMaster Tricolour Edition is a bold expression of identity and global vision. Its extraordinary dial showcases 3D hand-carved continents rising from a deep royal blue base At the heart, an open flywheel reveals the living mechanics beneath — a reminder that time moves with purpose. The dial’s saffron, white, and green accents create a striking tri-tone composition, symbolising strength, balance, and ambition.The sculpted world map appears almost suspended beneath the curved crystal, delivering remarkable depth and dimension. Paired with a premium leather strap and butterfly clasp, this timepiece blends cultural character with mechanical artistry.Crafted for leaders, collectors, and visionaries — the WorldMaster Tricolour is not just worn. It is represented. Specifications Movement: Automatic mechanical movement, Power Reserve: ~40 hours, Frequency 21600 times/hour, Stop second function, Automatic/manual winding Power Reserve: 52 Hours Jewels: 33 Synthetic Rubies Frequency: 28,800 VPH (4.0 Hz) Case Material: STAINLESS STEEL Glass: SAPPHIRE CRYSTAL GLASS Case Diameter: 44mm Water Resistance: 50M (5 ATM) Strap: LEATHER (BLACK) Clasp: Push Button Hidden Clasp Warranty: 24.0 Months Official Manufacturer Warranty Compliance & Care Country of Origin: People’s Republic of China Manufacturer: Guangzhou Hengbaoluo Technology Co., Ltd. Importer / Packer: Rise N Be Original Lifestyle Pvt Ltd, Building No. 3, 4th Floor, Block M, DLF City Phase II, Road Number 5, Sector 25, Gurugram, Haryana 122008, India",
