    "name": "AeroTwin 997 Series – Dual Movement Skeleton Watch (Rose Gold & Black Edition)",
    "title": "AeroTwin 997 Series – Dual Movement Skeleton Watch (Rose Gold & Black Edition)",
    "subtitle": "The AeroTwin 997 Series is an exploration of precision, form, and mechanical expression.Defined by its dual-engine architecture, the dial reveals a controlled interplay between movement and structure. A partially open-worked design exposes the rhythm of the mechanism, while maintaining a sense of balance and restraint.Crafted in 304 stainless steel with a rose gold finish, the case reflects strength with refinement. The black strap anchors the composition, offering contrast and continuity.Every detail serves a purpose. Nothing is excess.The AeroTwin 997 Series is not simply worn. It is experienced. Specifications Movement: Automatic Multifunction movement, 304 Stainless Steel case, Power Reserve: 40 hours, Frequency 21600 times/hour, Stop second function, Automatic/manual winding Power Reserve: ~42 Hours Jewels: 24 Synthetic Rubies Frequency: 28,800 BPH (4 Hz) Case Material: STAINLESS STEEL Glass: SAPPHIRE Case Diameter: 42mm Water Resistance: 50M Strap: LEATHER (BLACK) Clasp: DOUBLE PRESS BUTTERFLY CLASP Warranty: 24.0 Months Official Manufacturer Warranty Compliance & Care Country of Origin: People’s Republic of China Manufacturer: Guangzhou Hengbaoluo Technology Co., Ltd. Importer / Packer: Rise N Be Original Lifestyle Pvt Ltd, Building No. 3, 4th Floor, Block M, DLF City Phase II, Road Number 5, Sector 25, Gurugram, Haryana 122008, India",
